# -*- coding: utf-8 -*-
"""BROWN 8 BOULES - maquette de Maeva, 12 cartons par feuille (06/10).

REGLE ABSOLUE : le decor EST son carton (le mot BROWN, l'hibiscus, la bande
B-I-N-G-O, les huit cases a coins ronds), releve au trait sur sa planche.
RIEN n'a ete redessine ni ajoute.

CE QUI CHANGE (sceau Maeva 06/10 : 12 grilles au lieu de 16) : on ne garde
plus la disposition 4x4 de l'image. On reprend UN carton et on le pose 12
fois, en 3 colonnes x 4 rangees. Chaque carton est donc PLUS GRAND et les
chiffres plus gros. Le dessin du carton ne bouge pas d'un trait.

REGLE DU JEU INCHANGEE :
   B 1-15 (2) . I 16-30 (1) . N 31-45 (2) . G 46-60 (1) . O 61-75 (2)
   HUIT numeros, tries du plus petit en haut au plus grand en bas. Crieur 1-75.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

try:
    from generators import securite as _sec
except Exception:
    try:
        import securite as _sec
    except Exception:
        _sec = None

import os as _os
try:
    pdfmetrics.registerFont(TTFont("LMROMANB8", _os.path.join(
        _os.path.dirname(_os.path.abspath(__file__)), "LatinModern.ttf")))
    _POLICE_ECO = "LMROMANB8"
except Exception:
    try:
        pdfmetrics.registerFont(TTFont("DJLB8", "/usr/share/fonts/truetype/dejavu/DejaVuSans-ExtraLight.ttf"))
        _POLICE_ECO = "DJLB8"
    except Exception:
        _POLICE_ECO = "Helvetica"
POLICE = _POLICE_ECO
_GRIS_ECO = colors.Color(0.40, 0.40, 0.40)
_POLICE_P15 = "Helvetica-Bold"
_GRIS_P15 = colors.Color(0.14, 0.14, 0.14)
_GRAS_TRAIT = 0.012

def _style_chiffres(style):
    if str(style).lower() in ("p15", "premium"):
        return _POLICE_P15, _GRIS_P15
    return _POLICE_ECO, _GRIS_ECO

RAINBOW = [
    "#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
    "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41",
]
GRIS = colors.Color(0.42, 0.42, 0.42)
GRIS_CLAIR = colors.Color(0.80, 0.80, 0.80)
TRAIT_NB = "#555555"

PAGE_W, PAGE_H = landscape(A4)
ASPECT = 1.767
COLS_PAGE = 3
ROWS_PAGE = 4
CARTES_PAGE = COLS_PAGE * ROWS_PAGE

MARGE = 6 * mm
GUTTER = 4 * mm
CELL_H = (PAGE_H - 2 * MARGE - (ROWS_PAGE - 1) * GUTTER) / ROWS_PAGE
CELL_W = CELL_H * ASPECT
GRID_W = COLS_PAGE * CELL_W + (COLS_PAGE - 1) * GUTTER
X_START = (PAGE_W - GRID_W) / 2.0

PLAGES = [("B", 1, 15, 2), ("I", 16, 30, 1), ("N", 31, 45, 2),
          ("G", 46, 60, 1), ("O", 61, 75, 2)]

CELLULES = [
    (1, 15, [(0.0258, 0.4155, 0.1680, 0.2511), (0.0233, 0.6895, 0.1705, 0.2557)]),
    (16, 30, [(0.2196, 0.5251, 0.1731, 0.2968)]),
    (31, 45, [(0.4160, 0.4155, 0.1680, 0.2511), (0.4160, 0.6895, 0.1680, 0.2557)]),
    (46, 60, [(0.6124, 0.5251, 0.1731, 0.2968)]),
    (61, 75, [(0.8088, 0.4110, 0.1731, 0.2557), (0.8088, 0.6895, 0.1731, 0.2603)]),
]


def _positions():
    pos = []
    for r in range(ROWS_PAGE):
        for col in range(COLS_PAGE):
            px = X_START + col * (CELL_W + GUTTER)
            py = PAGE_H - MARGE - (r + 1) * CELL_H - r * GUTTER
            pos.append((px, py))
    return pos


def _graver_planche(c):
    nom = "BROWN8_12_DECOR"
    if not getattr(c, "_b8_12_forme", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CELL_W, uppery=CELL_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0; n = len(contour)
            while i < n:
                cmd = contour[i]; j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * CELL_W, CELL_H - v[1] / 1000.0 * CELL_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * CELL_W, CELL_H - v[1] / 1000.0 * CELL_H)
                else:
                    p.curveTo(v[0] / 1000.0 * CELL_W, CELL_H - v[1] / 1000.0 * CELL_H,
                              v[2] / 1000.0 * CELL_W, CELL_H - v[3] / 1000.0 * CELL_H,
                              v[4] / 1000.0 * CELL_W, CELL_H - v[5] / 1000.0 * CELL_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._b8_12_forme = True
    return nom


def _gen_grille(rng):
    return [sorted(rng.sample(range(a, b + 1), n)) for _l, a, b, n in PLAGES]


def _tirer(rng, deja):
    for _ in range(400):
        g = _gen_grille(rng)
        cle = tuple(tuple(r) for r in g)
        if cle not in deja:
            deja.add(cle); return g
    return g


def _dessiner_feuille(c, grilles, series, couleurs, style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    nom = _graver_planche(c)
    for gi, (px, py) in enumerate(_positions()):
        c.saveState()
        fen = c.beginPath(); fen.rect(px, py, CELL_W, CELL_H)
        c.clipPath(fen, stroke=0, fill=0)
        c.setFillColor(couleurs[gi])
        c.translate(px, py)
        c.doForm(nom)
        c.restoreState()
        grille = grilles[gi]
        for ci, (lo, hi, cases) in enumerate(CELLULES):
            for ri, (fx, fy, fw, fh) in enumerate(cases):
                val = grille[ci][ri]
                cx = px + (fx + fw / 2.0) * CELL_W
                cy = py + CELL_H - (fy + fh / 2.0) * CELL_H
                # ⭐ 06/10 (sceau Maeva : « pousse au maximum ») : le plus gros
                #    chiffre qui tient dans la bulle. On dimensionne sur « 88 »
                #    (le plus large) avec une marge de 0,90.
                _w88 = pdfmetrics.stringWidth("88", police_ch, 1.0)
                tnum = min(fw * CELL_W * 0.90 / _w88, fh * CELL_H * 0.90 / 0.72)
                if _sec:
                    _sec.chiffre_micro(c, val, cx, cy - tnum * 0.34, tnum, gris_ch, police_ch, epaisseur=_GRAS_TRAIT)
                else:
                    c.setFillColor(gris_ch); c.setFont(police_ch, tnum)
                    c.drawCentredString(cx, cy - tnum * 0.34, str(val))
        c.setFillColor(GRIS); c.setFont(POLICE, 7)
        c.drawString(px + CELL_W * 0.11, py + CELL_H * 0.90, "%06d" % series[gi])
        if _sec:
            try:
                _sec.cadre_micro(c, px, py, CELL_W, CELL_H, series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_cartes=12, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", motif="", page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4), pageCompression=1)
    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE
    rng = random.Random(880000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()
    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.4 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.4 * mm, "%03d" % no_page)
        grilles = [_tirer(rng, _deja) for _k in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        couleurs = [colors.HexColor(
            couleur_perso if (couleur and couleur_perso)
            else RAINBOW[(s - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
            for s in series]
        _dessiner_feuille(c, grilles, series, couleurs, style=style)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1
    c.save(); buf.seek(0)
    return buf


if __name__ == "__main__":
    open("test_brown8_12.pdf", "wb").write(generer_pdf(nb_cartes=12).read())
    print("BROWN 8 - 12 cartons genere")

